func:
// The virtual switch emits its state right after a deploy. Without this
// guard the flow would write the setting and restart the GX display every
// time Node-RED is deployed.
var started = context.get('startedAt') || 0;
if (Date.now() - started < 5000) {
    node.status({fill: 'grey', shape: 'ring', text: 'ignored (just deployed)'});
    return null;
}

// Accepts 1/0, true/false, "on"/"off" or an object with .state -
// depending on what the virtual switch delivers.
var p = msg.payload;
if (p !== null && typeof p === 'object') {
    p = (p.state !== undefined) ? p.state : p.value;
}
var on = (p === 1 || p === true || p === '1' || p === 'on');
var value = on ? 1 : 0;

// Read the setting first and only act on a real change - a driver restart
// plus a GUI restart is nothing to trigger for nothing. Writing the settings
// value, not the device path /Mode!
var path = '/Settings/Devices/tsbuckboost/SeparateTempSensors';
msg.payload =
    'P=' + path + '; V=' + value + '; ' +
    'CUR=$(dbus -y com.victronenergy.settings $P GetValue | tr -d " \\n"); ' +
    'if [ "$CUR" = "$V" ]; then echo unchanged; else ' +
    '( dbus -y com.victronenergy.settings $P SetValue $V && ' +
    'svc -t /service/TsBuckBoost && sleep 3 && svc -t /service/start-gui && ' +
    'echo switched ) || echo failed; fi';
msg.tsbbValue = value;
node.status({fill: 'blue', shape: 'dot', text: 'switching to ' + value});
return msg;

initialize:
// Remember when this node came up, so the first messages after a
// deploy can be ignored.
context.set('startedAt', Date.now());

func:
// Wired to the first exec output. The command always echoes exactly one
// keyword, so one message per run and no guessing.
var out = String(msg.payload || '').trim();
var state = msg.tsbbValue === 1 ? 'on' : 'off';

if (out.indexOf('switched') >= 0) {
    msg.payload = 'separate temperature devices ' + state
        + ', driver and GX display restarted';
} else if (out.indexOf('unchanged') >= 0) {
    msg.payload = 'already ' + state + ', nothing to do';
} else {
    msg.payload = 'failed - is Node-RED allowed to run commands on the GX'
        + ' device? (' + out + ')';
}
return msg;
